# shieldgamma: each rule of src/quest/combat/shieldgamma.cpp (and its targets) removed once; src/quest/tests/shieldgamma_test.cpp must fail on every one.
# runm <module> <name> <file under src/quest/combat> <sed expression>
runm shieldgamma sg_scope_ignored      shieldgamma.cpp 's/^  if (!scope::InCombat()) return original(node, data);$//'
runm shieldgamma sg_scope_inverted     shieldgamma.cpp 's/if (!scope::InCombat()) return original(node, data);/if (scope::InCombat()) return original(node, data);/'
runm shieldgamma sg_enroll_skipped     shieldgamma.cpp 's/if (!scope::Enroll()) return Refused/if (false) return Refused/'
runm shieldgamma sg_mat_ignored        shieldgamma.cpp 's/At<std::uint64_t>(d, kDataMaterial) != kMaterial || //'
runm shieldgamma sg_type_ignored       shieldgamma.cpp 's/ || At<std::int32_t>(d, kDataType) != kVec4//'
runm shieldgamma sg_space_ignored      shieldgamma.cpp 's/ || At<std::int32_t>(d, kDataSpace) != kLinear//'
runm shieldgamma sg_gamma_exponent     shieldgamma_targets.h 's/kGamma = 2.2f/kGamma = 2.0f/'
runm shieldgamma sg_no_clamp_hi        shieldgamma.cpp 's/(x > 1.0f ? 1.0f : x)/x/'
runm shieldgamma sg_no_clamp_lo        shieldgamma.cpp 's/x < 0.0f ? 0.0f : //'
runm shieldgamma sg_no_restore         shieldgamma.cpp 's/^  std::memcpy(value, was, sizeof was);$/  (void)was;/'
runm shieldgamma sg_alpha_written      shieldgamma.cpp 's/std::memcpy(value, now, sizeof now);/std::memcpy(value, now, sizeof now); std::memset(value + 12, 0, 4);/'
runm shieldgamma sg_gamma_flag_ignored shieldgamma.cpp 's/^  if (!g_gamma.load(std::memory_order_relaxed)) return original(node, data);$//'
runm shieldgamma sg_mirror_flag_ignored shieldgamma.cpp 's/g_mirror.load(std::memory_order_relaxed) \&\& prop == kRingProperty/prop == kRingProperty/'
runm shieldgamma sg_mirror_any_prop    shieldgamma.cpp 's/ \&\& prop == kRingProperty//'
runm shieldgamma sg_mirror_same_mat    shieldgamma.cpp 's/^    std::memcpy(copy + kDataMaterial, \&kTubeMaterial, sizeof kTubeMaterial);$//'
runm shieldgamma sg_mirror_undecoded   shieldgamma.cpp 's/^    std::memcpy(copy + kDataValue, now, sizeof now);$//'
runm shieldgamma sg_mirror_on_orig     shieldgamma.cpp 's/^    original(node, copy);$/    original(node, data);/'
runm shieldgamma sg_mirror_result      shieldgamma.cpp 's/^    original(node, copy);$/    return original(node, copy);/'
runm shieldgamma sg_mirror_skipped     shieldgamma.cpp 's/^    original(node, copy);$/    (void)copy;/'
runm shieldgamma sg_unreadable_drops   shieldgamma.cpp 's/g_unreadable.fetch_add(1, std::memory_order_relaxed);/g_unreadable.fetch_add(1, std::memory_order_relaxed); return 0;/'
runm shieldgamma sg_off_installs       shieldgamma.cpp 's/if (!gamma \&\& !tubeMirror) {/if (false) {/'
runm shieldgamma sg_decode_unthinned   shieldgamma.cpp 's/if (n \& (n - 1)) return;.*$//'
runm shieldgamma sg_refusal_quiet      shieldgamma.cpp 's/sentinel::LogFields(ok ? sentinel::LogLevel::kInfo : sentinel::LogLevel::kError, "combat_shieldgamma_install"/sentinel::LogFields(sentinel::LogLevel::kInfo, "combat_shieldgamma_install"/'
runm shieldgamma sg_wrong_slot         shieldgamma_targets.h 's/kSlotVaddr = 0x36d2020ULL/kSlotVaddr = 0x36d2028ULL/'
runm shieldgamma sg_wrong_fn           shieldgamma_targets.h 's/kFnVaddr = 0x272d55cULL/kFnVaddr = 0x272d560ULL/'
runm shieldgamma sg_wrong_mat          shieldgamma_targets.h 's/kMaterial = 0xdbde1b05fa8f6200ULL/kMaterial = 0xdbde1b05fa8f6201ULL/'
runm shieldgamma sg_wrong_tube         shieldgamma_targets.h 's/kTubeMaterial = 0xb28e940eb21a5798ULL/kTubeMaterial = 0xb28e940eb21a5799ULL/'
runm shieldgamma sg_wrong_ring         shieldgamma_targets.h 's/kRingProperty = 0xdd35e419672ee0baULL/kRingProperty = 0xdd35e419672ee0bbULL/'
runm shieldgamma sg_original_unchecked shieldgamma_targets.h 's/^  target.expectedOriginal = .*$/  (void)base;/'
